def page(fn, title, pg, body, css="", js="", gsapjs="", light=True, dark=False, cfg="", head="", scripts=""):
    c = cfg + (' data-navlight="1" data-solid-at="0.08"' if light and not dark else "")
    html = SHELL.format(desc=DESC.get(fn,"Boost Club, a nutrition club next to Piața Victoriei in Bucharest. Start with a free body scan."), title=title, head=head, css=css, bodycls=' class="dark"' if dark else "", page=pg, cfg=c, body=body, js=js, gsapjs=gsapjs, scripts=scripts)
    open(os.path.join(D, fn), "w").write(html)
    print("wrote", fn)

def hero(eyebrow, h, sub, ctas, img=None, alt="", slot="", pos="50% 50%", dark=False, portrait=False):
    if img and portrait:
        return f'''<section class="phero gut{' night' if dark else ''}"><div class="wrap phsplit">
  <div><span class="eyebrow">{eyebrow}</span>
  <h1 class="h-xl">{h}</h1>
  <p class="lead sub">{sub}</p>
  <div class="row" style="margin-top:28px">{ctas}</div></div>
  <div class="frame phport" data-slot="{slot}"><img src="{img}" alt="{alt}" style="object-position:{pos}"></div>
</div></section>'''
    fr = f'<div class="frame pframe" data-slot="{slot}"><img src="{img}" alt="{alt}" style="object-position:{pos}"></div>' if img else ""
    return f'''<section class="phero gut{' night' if dark else ''}"><div class="wrap">
  <span class="eyebrow">{eyebrow}</span>
  <h1 class="h-xl">{h}</h1>
  <p class="lead sub">{sub}</p>
  <div class="row" style="margin-top:28px">{ctas}</div>
  {fr}
</div></section>'''

