def faq(items):
    return '<div class="faq">' + "".join(f"<details><summary>{q}</summary><p>{a}</p></details>" for q, a in items) + "</div>"

def ruled(items, dark=False):
    return '<ol class="ruled">' + "".join(f'<li><span class="k">{k}</span><div><h3>{h}</h3><p>{p}</p></div></li>' for k, h, p in items) + "</ol>"

STATS_CSS = ".stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--line-l);margin-top:56px}.stats div{padding:22px 20px 22px 0;border-right:1px solid var(--line-l)}.stats div+div{padding-left:20px}.stats div:last-child{border-right:0}.stats b{display:block;font-size:clamp(28px,3vw,44px);font-weight:600;letter-spacing:-.04em;line-height:1}.stats span{font-size:12px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--stone)}.night .stats,.night .stats div,.on-dark .stats,.on-dark .stats div{border-color:var(--line-d)}.night .stats span{color:var(--sage)}@media (max-width:800px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.stats div{border-right:0;border-bottom:1px solid var(--line-l);padding-left:0!important}}"
