# ---------- Gabriel ----------
page("gabriel.html", "About Gabriel", "gabriel",
'''<section class="phero gut night"><div class="wrap gh"><div><span class="eyebrow">Boost Club founder</span><h1 class="h-xl">Gabriel <span class="it">Neshto.</span></h1>
<p class="lead sub muted">ISSA-certified personal trainer, semi-professional MMA fighter and track &amp; field athlete, third generation of a family with 36 years in wellness, and someone who built his own body from zero: over 20 kg of muscle.</p>
<p class="muted" style="max-width:46ch">I don't sell you a perfect plan. I offer a realistic direction, built around your life, not the other way around.</p>
<div class="row" style="margin-top:22px"><a class="btn btn-brass" href="#" data-reserve>Book a consultation with Gabriel <span class="ar">→</span></a></div></div>
<div class="frame gimg" data-slot="REAL · Gabriel at the club"><img src="img/real/gabi-sign-pointing.jpg" alt="Gabriel Neshto at the green wall of Boost Club, next to the sign and the results wall" style="object-position:50% 40%"></div></div>'''
+ stats([("ISSA","Certified personal trainer"),("+20 kg","Muscle built"),("~30,000","Followers"),("20+","Countries")]) + "</div></section>"
+ '<section class="sec gut"><div class="wrap grid2" style="align-items:start"><div><span class="eyebrow">Credentials</span><h2 class="h-l">Why you can <span class="it">trust him.</span></h2></div>'
+ ruled([("ISSA","ISSA accredited","Certified Personal Trainer from the International Sports Sciences Association, backed by years of systematic study in sports science, nutrition and health."),("Athlete","Competing athlete","Over 20 kg of muscle built through proper nutrition and training. Competes as a semi-professional MMA fighter and track & field athlete."),("Family","36 years of heritage","The Neshto family has worked in wellness for 36 years and guided thousands of people. Gabriel grew up in this environment and carries the tradition forward."),("World","International community","Clients from over 20 countries, from France, Switzerland and the UK to the USA, India and Singapore. Close to 30,000 followers online.")]) + "</div></section>"
+ '<section class="sec on-dark gut"><div class="wrap grid2" style="align-items:start"><div><span class="eyebrow">The story</span><h2 class="h-l">Gabriel\'s <span class="it">journey.</span></h2><div class="frame" style="aspect-ratio:4/5;margin-top:28px;max-width:420px" data-slot="REAL · painting the wall"><img src="img/his/painting.webp" alt="Gabriel painting the green wall of the club" loading="lazy"></div><blockquote class="gq">"Information alone is not enough. You need a system, simplicity, and people beside you. That changed everything for me and it\'s exactly what I build for my clients today."</blockquote></div>'
+ ruled([("01","The starting point","Underweight, living chaotically, with close to zero confidence."),("02","The change","Proper nutrition + structured training → over 20 kg of muscle."),("03","Sport","Today he competes as a semi-pro MMA fighter and track & field athlete."),("04","The training","Years studying sports science and nutrition, confirmed by the ISSA certification."),("05","Boost Club","All that experience comes home to Bucharest. You come in, measure your start, leave with a clear direction.")]) + "</div></section>"
+ '''<section class="sec gut"><div class="wrap grid2"><div class="frame" style="aspect-ratio:4/5"><img src="img/mma.jpg" alt="Gabriel training in an MMA cage" loading="lazy" style="object-position:50% 30%"></div><div><span class="eyebrow">Sport &amp; community</span><h2 class="h-l">From the ring and the track, <span class="it">into the club.</span></h2><p class="lead muted" style="margin-top:20px">The discipline of MMA and athletics is the same discipline Gabriel brings to consultations: measurable steps, executed consistently, no shortcuts.</p><p class="muted">Close to 30,000 people follow him on social media, where his content on nutrition, training and lifestyle has gathered millions of views.</p><div class="row" style="margin-top:16px"><a class="btn btn-ghost" href="https://www.instagram.com/gabineshto" target="_blank" rel="noopener">@gabineshto on Instagram</a><a class="btn btn-ghost" href="https://gabrielneshto.com" target="_blank" rel="noopener">gabrielneshto.com</a></div></div></div></section>
<section class="sec oat gut"><div class="wrap"><div class="famtx"><span class="eyebrow">Family heritage</span><h2 class="h-l">36 years of wellness. <span class="it">A tradition that continues.</span></h2><p class="muted" style="margin-top:20px">The Neshto family has worked in nutrition and wellness since 1989. Over these decades, they have guided thousands of people of all ages, with all types of goals. Gabriel is the natural continuation of this tradition, with a younger, more modern perspective closer to the pace of life today.</p><p class="muted">This means that behind Boost Club stands not an entrepreneur who read a few books, but a family that has seen what works on thousands of real people, in real time, for nearly four decades.</p></div><div class="fam"><div class="frame" style="aspect-ratio:3/4"><img src="img/family.jpg" alt="The Neshto family in a TV studio" loading="lazy" style="object-position:50% 30%"></div><div class="frame" style="aspect-ratio:3/4" data-slot="REAL"><img src="img/his/gabi-kiss.webp" alt="Gabriel at the club with the youngest member of the family" loading="lazy" style="object-position:50% 30%"></div><div class="frame" style="aspect-ratio:3/4" data-slot="REAL"><img src="img/real/gabi-gala-group.jpg" alt="Gabriel with his family and team on stage at a gala" loading="lazy" style="object-position:50% 40%"></div></div></div></section>
<section class="sec gut"><div class="wrap"><span class="eyebrow">Philosophy</span><h2 class="h-l">The 3 S philosophy: <span class="it">Systems, Simplicity, Support.</span></h2><p class="lead muted" style="margin:18px 0 32px">Health doesn't run on willpower. It runs on three things built correctly.</p>'''
+ ruled([("S1","Systems","On a busy day, a simple plan can make choices easier. Together, we look for habits you can fit into your daily routine."),("S2","Simplicity","If your \"healthy\" breakfast takes an hour in the morning, half-asleep, plus a mountain of dishes, you'll end up doing neither. What's simple gets done. What's complicated gets postponed."),("S3","Support","The best students in the world have teachers. The best athletes have coaches. The best doctors have mentors. Yet most people think health is something to figure out alone. News flash: you don't have to.")])
+ f'</div></section><section class="sec on-dark gut"><div class="wrap"><span class="eyebrow">First step</span><h2 class="h-xl">Come and <span class="it">meet us.</span></h2><p class="lead muted" style="margin-top:20px">The first consultation is free and takes 25–30 minutes. You leave with real data and a clear next step.</p><div class="row" style="margin-top:24px"><a class="btn btn-brass" href="#" data-reserve>Book a consultation with Gabriel <span class="ar">→</span></a><a class="btn btn-ghost" href="{WA}" target="_blank" rel="noopener">Message on WhatsApp</a></div></div></section>',
css=".gh{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:clamp(28px,5vw,72px);align-items:end}@media (max-width:900px){.gh{grid-template-columns:minmax(0,1fr)}}.famtx{max-width:760px}.fam{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:44px}@media (max-width:600px){.fam{grid-template-columns:1fr 1fr}.fam>:first-child{grid-column:1/-1;aspect-ratio:4/5!important}}.gimg{aspect-ratio:4/5}.gimg img{object-position:50% 25%}.gq{margin:28px 0 0;font-family:var(--accent);font-style:italic;font-weight:500;font-size:clamp(26px,2.8vw,40px);line-height:1.12}" + STATS_CSS,
light=False, dark=True)

